const frames = error =>
  String(error?.stack)
    .split("\n")
    .slice(1, 7)
    .map(line =>
      line
        .trim()
        .replace(/^at /, "")
        .replace(/\(.*[\\/]/, "(")
        .replace(/^[^ ]*[\\/]/, ""),
    )
    .join(" < ");
class Other {}
const forwarding = {
  apply(target, receiver, operands) {
    return Reflect.apply(target, receiver, operands);
  },
  construct(target, operands, newTarget) {
    return Reflect.construct(target, operands, newTarget);
  },
};
const ways = {
  "call": (callee, given) => callee(...given),
  "call of one": (callee, given) => callee(given[0]),
  "call of two": (callee, given) => callee(given[0], given[1]),
  ".call": (callee, given) => callee.call(undefined, ...given),
  ".apply": (callee, given) => callee.apply(undefined, given),
  "Reflect.apply": (callee, given) => Reflect.apply(callee, undefined, given),
  "new": (callee, given) => new callee(...given),
  "new of one": (callee, given) => new callee(given[0]),
  "new of two": (callee, given) => new callee(given[0], given[1]),
  "Reflect.construct": (callee, given) => Reflect.construct(callee, given),
  "Reflect.construct for another": (callee, given) => Reflect.construct(callee, given, Other),
  "super": (callee, given) =>
    new (class Heir extends callee {
      constructor(...operands) {
        super(...operands);
      }
    })(...given),
  "super of two": (callee, given) =>
    new (class Heir extends callee {
      constructor(first, second) {
        super(first, second);
      }
    })(given[0], given[1]),
  "super nobody wrote": (callee, given) => new (class Heir extends callee {})(...given),
  "bound": (callee, given) => callee.bind(undefined)(...given),
  "bound with its operands": (callee, given) => callee.bind(undefined, ...given)(),
  "new bound": (callee, given) => new (callee.bind(undefined))(...given),
  "new bound with its operands": (callee, given) => new (callee.bind(undefined, ...given))(),
  "proxy": (callee, given) => new Proxy(callee, {})(...given),
  "new proxy": (callee, given) => new (new Proxy(callee, {}))(...given),
  "proxy that forwards": (callee, given) => new Proxy(callee, forwarding)(...given),
  "new proxy that forwards": (callee, given) => new (new Proxy(callee, forwarding))(...given),
};
export function enterEveryWay(label, callee, lists) {
  const rows = [];
  for (const way in ways) {
    lists.forEach((given, index) => {
      let end;
      try {
        const result = ways[way](callee, given);
        end = typeof result === "object" || typeof result === "function" ? typeof result : String(result);
      } catch (error) {
        end = error?.constructor?.name + ": " + frames(error);
      }
      rows.push(label + " | " + way + " | " + index + " | " + end);
    });
  }
  return rows;
}
